const fs = require('fs');
const path = require('path');
const dir = path.join(__dirname, 'src', 'assets', 'i18n');

const map = {
  fr: 'Aucune galaxie du catalogue visible maintenant.',
  en: 'No catalog galaxies visible right now.',
  de: 'Keine Galaxie aus dem Katalog ist gerade sichtbar.',
  es: 'Ninguna galaxia del catálogo visible ahora.',
  it: 'Nessuna galassia del catalogo visibile ora.',
  ru: 'Сейчас нет видимых галактик из каталога.',
  cn: '当前目录中没有可见的星系。',
  jp: '現在カタログに表示できる銀河はありません。',
  ar: 'لا توجد مجرات من الكتالوج مرئية الآن.',
  he: 'אין כרגע גלקסיות נראות מהקטלוג.',
  el: 'Καμία γαλαξία του καταλόγου δεν είναι ορατή τώρα.',
  in: 'Tidak ada galaksi katalog yang terlihat saat ini.'
};

for (const [lang, text] of Object.entries(map)) {
  const file = path.join(dir, `${lang}.json`);
  const data = JSON.parse(fs.readFileSync(file, 'utf8'));
  data.ASTRO_COMPASS.GALAXIES_NONE_VISIBLE = text;
  fs.writeFileSync(file, JSON.stringify(data, null, 2) + '\n', 'utf8');
  console.log(lang, 'ok');
}
